entries[198100] = { ["name"] = "Kleptomanie", ["text"] = "Ersetzt Zauberraub\n20% von Grundmana 40 Meter Reichweite\nKanalisiert (Wirken in 4 sek.) 20 sek. Abklingzeit\nEntfesselt einen Hagel disruptiver Magie auf Euer Ziel und raubt ihm 4 Sek. lang alle 0.5 Sek. einen nützlichen Magieeffekt.\n\nKann aus der Bewegung heraus gewirkt werden, aber während der Kanalisierung ist Eure Bewegungsgeschwindigkeit um 40% verringert." }
