entries[198103] = { ["name"] = "Erdelementar", ["text"] = "40 Meter Reichweite\nSofort 5 min Abklingzeit\nRuft einen großen Erdelementar herbei, der Euch und Eure Verbündeten 1 Min. lang beschützt.\n\nWährend dieser Elementar aktiv ist, ist Eure maximale Gesundheit um 15% erhöht." }
