entries[198109] = { ["name"] = "Unkontrollierter Aufprall", ["text"] = "Sofort\nWenn Ursoc sein markiertes Ziel erreicht, fügt er allen Spielercharakteren 42211 körperlichen Schaden zu. Dieser Effekt wird durch jeden Spielercharakter, durch den Ursoc gestürmt ist, verringert." }
