entries[198149] = { ["name"] = "Gefrorene Kugel", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort 1 min Abklingzeit\nSchleudert eine gefrorene Kugel auf einen Zielort, die wirbelndes Eis hervorruft, das allen Gegnern in der Nähe im Verlauf von 12 Sek. [20 * (13.2% der Zaubermacht)] Frostschaden zufügt. Gewährt 1 Aufladung von 'Eisige Finger', sobald die Kugel dem ersten Gegner Schaden zufügt.\n\nGegner, die von der Frostkugel getroffen wurden, werden für 3 Sek. um 30% verlangsamt." }
