entries[198486] = { ["name"] = "Alphawolf", ["text"] = "100 Meter Reichweite\nSofort\nWenn Eure Wildgeister aktiv sind und Ihr 'Kettenblitzschlag' und 'Tobende Blitze' einsetzt, greifen Eure Wölfe die nächsten 8 Sek. lang alle Gegner in der Nähe an und fügen ihnen alle 2 Sek. [(16% der Angriffskraft) * 1.13 * 1.26] körperlichen Schaden zu." }
entries[198487] = { ["name"] = "Zenimpuls", ["text"] = "40 Meter Reichweite\nSofort\nDie regelmäßige Heilung von 'Erneuernder Nebel' hat eine Chance, dass Euer nächstes 'Beleben' zusätzlich 'Zenimpuls' auf seinem Ziel und allen Verbündeten mit 'Erneuernder Nebel' auslöst und sie um (160% der Zaubermacht) heilt, erhöht um 6% pro aktivem 'Erneuernder Nebel' bis maximal 30%." }
entries[198488] = { ["name"] = "Höllische Macht", ["text"] = "Nahkampfreichweite\nSofort\nDer Zaubernde entfesselt die ihm von Gul'dan verliehenen Teufelsenergien und erhöht so sein Nahkampfangriffstempo 10 Sek. lang um 50%. Zusätzlich erhalten alle Nahkampfangriffe eine Chance, zusätzlichen Feuerschaden zu verursachen." }
