entries[198505] = { ["name"] = "Schicksalswölfe", ["text"] = "Rang 1/ 1 Artefakt Boni\n100 Meter ReichweiteBenötigt Schicksalshammer\nDer Schicksalshammer erfüllt jeden Eurer Wildgeister entweder mit Feuer-, Frost- oder Blitzenergie und verleiht ihnen so eine zusätzliche Fähigkeit." }
entries[198506] = { ["name"] = "Wildgeist", ["text"] = "30 Meter Reichweite\nSofort\nRuft zwei [ Elementargeister : elementare ] [ Glyphe 'Geisterraptoren' : Geisterraptoren / Geisterwölfe ] herbei, die Euch 15 Sek. lang im Kampf unterstützen. Sie sind immun gegen bewegungseinschränkende Effekte, und jeder herbeigerufene [ Elementargeister : elementare ]Wildgeist erhöht den körperlichen Schaden, den Eure Fähigkeiten verursachen, um [ Elementargeister : 10 % / 15%] [ und deren Feuer-, Frost- oder Naturschaden um 10 % ].\n\n'Wildgeist' erzeugt sofort einen Stapel von 'Waffe des Mahlstroms' sowie 15 Sek. lang alle 3 Sek. einen weiteren Stapel." }
