entries[198981] = { ["name"] = "Auslöser", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nLeysteinerz (50), Lockerer Abzug (30), Übergroße Sprengkapsel (20), Scharfschützenzielfernrohr (2), Blut von Sargeras (50), Infernoschwefel (10)\nStellt einen Auslöser her.\nQuest:\nFinger am Abzug\nZone:\nDalaran\n\nAuslöser\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben." }
