entries[199155] = { ["name"] = "Stechender Schwarm", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nHüllt das Ziel in einen Schwarm stechender Insekten, die alle 1 Sek. 45 körperlichen Schaden verursachen.\n$[2\nAuf dem heroischen Schwierigkeitsgrad hat dieser Effekt eine Chance, das Ziel für 0.5 Sek. zu betäuben, wenn er Schaden verursacht. Spielercharaktere können den Schwarm angreifen und müssen ihn töten, um den Effekt zu entfernen.]", ["unresolvedValues"] = true }
