entries[199158] = { ["name"] = "Untergang", ["text"] = "Rang 1/ 3 Artefakt Boni\nBenötigt Ulthalesh, Sense der Totenwinde\nErhöht den kritischen Schaden von 'Agonie', 'Verderbnis', [ Seelendieb : 'Seelendieb' / 'Blutsauger'] und 'Instabiles Gebrechen' um 3%." }
entries[199159] = { ["name"] = "Säurespeer", ["text"] = "Sofort\nVardalla setzt zu einem durchbohrenden Wurf auf ihr Ziel an und fügt ihm nach bis Abbruch 199161 körperlichen Schaden zu.\n\nSpielercharaktere können sich zwischen ihr und dem Ziel hin- und herbewegen und sie so am Zielen hindern. Dadurch wird der Schaden zwischen allen unterbrechenden Spielercharakteren und dem Ziel aufgeteilt." }
