entries[199176] = { ["name"] = "Hakenzunge", ["text"] = "100 Energie 100 Meter Reichweite\nWirken in 6 sek.\nNaraxas hält ihr Ziel mit ihrer Hakenzunge fest, zieht es in ihr Maul und verursacht so 5 Sek. lang alle 1 Sek. 11880020 körperlichen Schaden. Lauft vor Naraxas weg, um zu verhindern, dass Ihr gefressen werdet. Jedes gefressene Ziel gewährt Naraxas einen zusätzlichen Stapel von 'Unersättlich'." }
